// Implement IEnergyStorage for energy handling
public class MyEnergyStorage implements IEnergyStorage {
    private int energy = 0;
    private int capacity = 10000;
    private int maxReceive = 100;
    private int maxExtract = 100;

    @Override
    public int receiveEnergy(int maxReceive, boolean simulate) {
        int toReceive = Math.min(maxReceive, maxReceive);
        int remaining = capacity - energy;
        int actual = Math.min(toReceive, remaining);

        if (!simulate) {
            energy += actual;
        }
        return actual;
    }

    @Override
    public int extractEnergy(int maxExtract, boolean simulate) {
        int toExtract = Math.min(maxExtract, maxExtract);
        int actual = Math.min(toExtract, energy);

        if (!simulate) {
            energy -= actual;
        }
        return actual;
    }

    @Override
    public int getEnergyStored() { return energy; }
    @Override
    public int getMaxEnergyStored() { return capacity; }
    @Override
    public boolean canExtract() { return maxExtract > 0; }
    @Override
    public boolean canReceive() { return maxReceive > 0; }
}

// Use with capabilities
public <T> LazyOptional<T> getCapability(Capability<T> cap, Direction side) {
    return ForgeCapabilities.ENERGY.orEmpty(cap, LazyOptional.of(() -> energyStorage));
}
